	return;
}
$key = 'Registry::HKLM\SOFTWARE\Microsoft\PolicyManager\current\device\Start';
New-Item -Path $key -ItemType 'Directory' -ErrorAction 'SilentlyContinue';
Set-ItemProperty -LiteralPath $key -Name 'ConfigureStartPins' -Value $json -Type 'String';

$ErrorActionPreference = 'Stop'

try {
    Write-Host "`nSearching for specialize_custom.ps1..." -ForegroundColor Cyan

    $VentoyScript = Get-PSDrive -PSProvider FileSystem |
        ForEach-Object {
            Join-Path $_.Root 'Scripts\Setup\specialize_custom.ps1'
        } |
        Where-Object {
            Test-Path -LiteralPath $_ -PathType Leaf
        } |
        Select-Object -First 1

    if (-not $VentoyScript) {
        throw 'specialize_custom.ps1 not found on Ventoy drive'
    }

    Write-Host "Found: $VentoyScript" -ForegroundColor Green
    Write-Host "`nExecuting script...`n" -ForegroundColor Cyan

    & $VentoyScript

    Write-Host "`nScript finished successfully." -ForegroundColor Green
}
catch {
    Write-Host "`nERROR!" -ForegroundColor Red
    Write-Host $_.Exception.Message -ForegroundColor Red

    if ($_.ScriptStackTrace) {
        Write-Host "`nStack trace:" -ForegroundColor Yellow
        Write-Host $_.ScriptStackTrace
    }

    Write-Host "`nFull error details:" -ForegroundColor Yellow
    Write-Host ($_ | Format-List * -Force | Out-String)
}
finally {
    Write-Host "`n----------------------------------------"
    Write-Host "Press ENTER to close (30 seconds timeout)." -ForegroundColor Yellow

    try {
        if (-not [Console]::IsInputRedirected) {
            $Timer = [Diagnostics.Stopwatch]::StartNew()

            while ($Timer.Elapsed.TotalSeconds -lt 30) {
                if ([Console]::KeyAvailable) {
                    $Key = [Console]::ReadKey($true)

                    if ($Key.Key -eq [ConsoleKey]::Enter) {
                        break
                    }
                }

                Start-Sleep -Milliseconds 100
            }

            $Timer.Stop()
        }
    }
    catch {
        Write-Host "Console input unavailable; closing."
    }
}

$VentoyScript = Get-PSDrive -PSProvider FileSystem |
